public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>();

    // Add all vertex mappings
    for (V vertex : graph.vertexSet()) {
        mapping.addVertexMapping(vertex, vertex);
    }

    // Add all edge mappings
    for (E edge : graph.edgeSet()) {
        mapping.addEdgeMapping(edge, edge);
    }

    return mapping;
}

public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    // Initialize the mapping
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>(graph, graph);

    // Define the mapping as a self-mapping
    graph.getVertices().forEach(v -> mapping.addVertexMapping(v, v));
    graph.getEdges().forEach(e -> mapping.addEdgeMapping(e, e));

    return mapping;
}

