/**
 * Enlarges this byte vector so that it can receive 'size' more bytes.
 * @param size number of additional bytes that this byte vector should be able to receive.
 */
public void enlarge(int size) {
    ByteBuffer oldBuffer = this.buffer;
    int newSize = oldBuffer.capacity() + size;
    ByteBuffer newBuffer = ByteBuffer.allocate(newSize).order(ByteOrder.LITTLE_ENDIAN);
    newBuffer.put(oldBuffer);
    newBuffer.position(oldBuffer.position());
    this.buffer = newBuffer;
}

private void enlarge(final int size) {
    // Check if the size is valid
    if (size < 1) {
        throw new IllegalArgumentException("Size must be a positive integer");
    }
    // Check if the current buffer is not big enough to fit the additional bytes
    if (size > data.length - position) {
        // Increase the size of the buffer by 50%
        int newSize = data.length + (data.length / 2);
        // Check if the new size is too small to fit the additional bytes
        if (newSize - position < size) {
            newSize = position + size;
        }
        // Create a new array with the new size
        byte[] newData = new byte[newSize];
        // Copy the old data to the new array
        System.arraycopy(data, 0, newData, 0, position);
        data = newData;
    }
}

