    // Step 1: Check if the input string is null or empty
    if (str == null || str.isEmpty()) {
        return str;
    }
    // Step 2: Find the last index of whitespace in the string
    int lastWhitespaceIndex = str.length() - 1;
    while (lastWhitespaceIndex >= 0 && Character.isWhitespace(str.charAt(lastWhitespaceIndex))) {
        lastWhitespaceIndex--;
    }
    // Step 3: Trim the string from the last index of whitespace to the end
    return str.substring(0, lastWhitespaceIndex + 1);
}

