private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // Step 1: Check if array is null
    if (array == null) {
        return Array.newInstance(newArrayComponentType, 1);
    }

    // Step 2: Check if array is already size 1
    if (Array.getLength(array) == 1) {
        return array;
    }

    // Step 3: Create new array of size 1 greater than input array
    int newArrayLength = Array.getLength(array) + 1;
    Object newArray = Array.newInstance(array.getClass().getComponentType(), newArrayLength);

    // Step 4: Copy values from input array to new array
    for (int i = 0; i < Array.getLength(array); i++) {
        Array.set(newArray, i, Array.get(array, i));
    }

    // Step 5: Set last value of new array to default
    Array.set(newArray, newArrayLength - 1, null);

    return newArray;
}

