public Set<V> intersection(Set<V> set1, Set<V> set2) {
    // handle invalid input sets
    if (set1 == null || set2 == null) {
        return Collections.emptySet();
    }

    // special case: if either set is empty, return empty set
    if (set1.isEmpty() || set2.isEmpty()) {
        return Collections.emptySet();
    }

    // optimization: if set1 is smaller than set2, swap them to reduce the number of iterations in the loop below
    if (set1.size() < set2.size()) {
        Set<V> temp = set1;
        set1 = set2;
        set2 = temp;
    }

    // iterate through the larger set and check if each element exists in the smaller set
    Set<V> result = new HashSet<>();
    for (V element : set1) {
        if (set2.contains(element)) {
            result.add(element);
        }
    }

    return result;
}

